```go
func tagEnd(src string, start int) int {
	i := start
	for i < len(src) {
		switch src[i] {
		case '"':
			// skip quoted string with escapes
			i++
			for i < len(src) {
				if src[i] == '\\' && i+1 < len(src) {
					i += 2
					continue
				}
				if src[i] == '"' {
					i++
					break
				}
				i++
			}
		case '}':
			if i+1 < len(src) && src[i+1] == '}' {
				return i
			}
			i++
		default:
			i++
		}
	}
	return -1
}
```

