type parser struct{ s string }

func (p *parser) skipSpace() { p.s = strings.TrimLeft(p.s, " \t") }

func ident(s string) (string, bool) {
	if s == "" { return "", false }
	c := s[0]
	if !isIdentStart(c) { return "", false }
	i := 1
	for i < len(s) && isIdentPart(s[i]) { i++ }
	return s[:i], true
}
