func (p *parser) parseName() (string, error) {
	p.skipSpace()
	first, ok := ident(p.s)
	if !ok {
		return "", fmt.Errorf("bad name %q in tag", first /*or snippet*/)
	}
	p.s = p.s[len(first):]
	name := first
	for strings.HasPrefix(p.s, ".") {
		rest := p.s[1:]
		part, ok := ident(rest)
		if !ok {
			return "", fmt.Errorf("bad name %q in tag", name+"."+snippet)
		}
		p.s = rest[len(part):]
		name += "." + part
	}
	return name, nil
}
