// Package tmpl implements a tiny text template engine.
//
// Render substitutes {{ name | filter | filter:"arg" }} tags in src using
// values looked up in data. Text outside tags is copied verbatim; "{{{{"
// renders as a literal "{{".
package tmpl

import (
	"fmt"
	"strconv"
	"strings"
)

// Render renders the template source src against data...
func Render(src string, data map[string]any) (string, error) {
	if data == nil {
		data = map[string]any{}
	}
	var b strings.Builder
	for i := 0; i < len(src); {
		if strings.HasPrefix(src[i:], "{{{{") {
			b.WriteString("{{")
			i += 4
			continue
		}
		if strings.HasPrefix(src[i:], "{{") {
			end := findTagEnd(src, i+2)
			if end < 0 {
				return "", fmt.Errorf(`unterminated tag: missing "}}"`)
			}
			out, err := evalTag(src[i+2:end], data)
			if err != nil {
				return "", err
			}
			b.WriteString(out)
			i = end + 2
			continue
		}
		b.WriteByte(src[i])
		i++
	}
	return b.String(), nil
}
```

