func (p *tagParser) applyFilter(text *string) error {
	p.skipSpace()
	start := p.s
	fn, ok := ident(p.s)
	if !ok {
		return fmt.Errorf("bad filter name in tag: %q", leading(start))
	}
	p.s = p.s[len(fn):]
