	if !known {
		return fmt.Errorf(`unknown filter %q`, fn)
	}
	p.skipSpace()
	arg, hasArg, err := p.parseArg(fn)
	if err != nil {
		return err
	}
	if spec.arity == 0 && hasArg {
		return fmt.Errorf(`filter %q takes no arguments`, fn)
	}
	if spec.arity == 1 && !hasArg {
		return fmt.Errorf(`filter %q requires an argument`, fn)
	}
	newText, err := applyFilter(fn, *text, arg)
	if err != nil {
		return err
	}
	*text = newText
	return nil
}
